 "content": "from collections import Counter


def transform(grid):
    """Restore zeroed cells in a framed, horizontally periodic color field."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # The fixed outer frame is constant in each of its regions.
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 1 if c < 2 else 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4

    # The interior is a row-wise repeating sequence. Find the shortest
    # plausible period from the visible cells, tolerating the few irregular
    # cells at the beginning of some rows.
    for r in range(3, h):
        known = [(c, out[r][c]) for c in range(3, w) if out[r][c] != 0]
        if not known:
            continue
        best = None
        for p in range(1, min(10, w - 3) + 1):
            groups = {}
            for c, v in known:
                groups.setdefault(c % p, []).append(v)
            score = sum(max(Counter(vals).values()) for vals in groups.values())
            # Penalize unnecessarily long periods; these puzzles use short
            # motifs, and multiples of the true period otherwise tie.
            rank = score - 0.025 * p * len(known)
            if best is None or rank > best[0]:
                best = (rank, p, groups)
        _, period, groups = best
        motif = {}
        for residue, vals in groups.items():
            counts = Counter(vals)
            motif[residue] = counts.most_common(1)[0][0]
        # Fill from the inferred row motif. Any unseen phase is completed from
        # the nearest available phase in the same row.
        for c in range(3, w):
            if out[r][c] == 0:
                if c % period in motif:
                    out[r][c] = motif[c % period]
                else:
                    nearest = min(motif, key=lambda k: min((k - c % period) % period,
                                                           (c % period - k) % period))
                    out[r][c] = motif[nearest]
    return out
"
}

